SELECT a.account_id, (SELECT MAX(A11) FROM district) - d.A11 AS gap FROM client c JOIN disp dp ON c.client_id = dp.client_id JOIN account a ON dp.account_id = a.account_id JOIN district d ON c.district_id = d.district_id WHERE c.gender = 'F' AND c.birth_date = (SELECT MIN(birth_date) FROM client WHERE gender = 'F') AND d.A11 = ( SELECT MIN(d2.A11) FROM client c2 JOIN district d2 ON c2.district_id = d2.district_id WHERE c2.gender = 'F' AND c2.birth_date = (SELECT MIN(birth_date) FROM client WHERE gender = 'F') )	financial
WITH accts AS ( SELECT DISTINCT a.account_id, a.date AS account_date, c.birth_date FROM client c JOIN disp d ON d.client_id = c.client_id AND d.type = 'OWNER' JOIN account a ON a.account_id = d.account_id JOIN district dist ON c.district_id = dist.district_id WHERE c.gender = 'F' AND c.birth_date < '1950-01-01' AND dist.A2 = 'Sokolov' ), loan_agg AS ( SELECT l.account_id, COUNT(*) AS total_loans, SUM(CASE WHEN l.status = 'A' THEN 1 ELSE 0 END) AS completed_loans, SUM(CASE WHEN l.status = 'D' THEN 1 ELSE 0 END) AS debt_loans FROM loan l GROUP BY l.account_id ) SELECT AVG((julianday(a.account_date) - julianday(a.birth_date)) / 365.25) AS avg_age_at_opening, SUM(COALESCE(l.total_loans, 0)) AS total_loans, SUM(COALESCE(l.completed_loans, 0)) AS completed_loans, SUM(COALESCE(l.debt_loans, 0)) AS debt_loans, MIN(STRFTIME('%Y', a.account_date)) AS earliest_year, MAX(STRFTIME('%Y', a.account_date)) AS latest_year FROM accts a LEFT JOIN loan_agg l ON l.account_id = a.account_id	financial
WITH dr AS ( SELECT district_id, A2, A3, RANK() OVER (ORDER BY A11 DESC) AS avg_salary_rank, RANK() OVER (ORDER BY A12 ASC) AS unemployment_rank FROM district ) SELECT dr.A2 AS district_name, dr.A3 AS region, dr.avg_salary_rank, dr.unemployment_rank, CAST(julianday(l.date) - julianday(a.date) AS INTEGER) AS days_open_before_loan, (SELECT COUNT(*) FROM client c WHERE c.district_id = dr.district_id) AS total_clients, (SELECT COUNT(*) FROM client c WHERE c.district_id = dr.district_id AND c.gender = 'F') AS female_clients, (SELECT COUNT(*) FROM client c WHERE c.district_id = dr.district_id AND c.gender = 'M') AS male_clients, (SELECT AVG((julianday(l.date) - julianday(c.birth_date))/365.25) FROM client c WHERE c.district_id = dr.district_id) AS avg_age, (SELECT COUNT(*) FROM trans t WHERE t.account_id = l.account_id AND t.date < l.date) AS transaction_count, (SELECT SUM(t.amount) FROM trans t WHERE t.account_id = l.account_id AND t.date < l.date AND t.type = 'PRIJEM') AS total_income FROM loan l JOIN account a ON a.account_id = l.account_id JOIN dr ON dr.district_id = a.district_id WHERE l.date = '1994-08-25'	financial
WITH accts AS ( SELECT a.account_id, a.date FROM account a JOIN district d ON d.district_id = a.district_id WHERE d.A2 = 'Litomerice' AND a.date >= '1996-01-01' AND a.date < '1997-01-01' ) SELECT (SELECT COUNT(*) FROM accts) AS total_accounts, (SELECT COUNT(DISTINCT c.client_id) FROM accts a JOIN disp di ON di.account_id = a.account_id JOIN client c ON c.client_id = di.client_id) AS total_clients, (SELECT COUNT(DISTINCT c.client_id) FROM accts a JOIN disp di ON di.account_id = a.account_id JOIN client c ON c.client_id = di.client_id WHERE c.gender = 'F') AS female_clients, (SELECT COUNT(DISTINCT c.client_id) FROM accts a JOIN disp di ON di.account_id = a.account_id JOIN client c ON c.client_id = di.client_id WHERE c.gender = 'M') AS male_clients, (SELECT AVG(1996 - CAST(STRFTIME('%Y', u.birth_date) AS REAL)) FROM ( SELECT DISTINCT c.client_id, c.birth_date FROM accts a JOIN disp di ON di.account_id = a.account_id JOIN client c ON c.client_id = di.client_id ) u) AS avg_age, (SELECT COALESCE(SUM(CASE WHEN t.type = 'PRIJEM' THEN t.amount ELSE 0 END), 0) FROM accts a JOIN trans t ON t.account_id = a.account_id) AS deposits, (SELECT COALESCE(SUM(CASE WHEN t.type = 'VYDAJ' THEN t.amount ELSE 0 END), 0) FROM accts a JOIN trans t ON t.account_id = a.account_id) AS withdrawals, (SELECT COALESCE(SUM(l.amount), 0) FROM accts a JOIN loan l ON l.account_id = a.account_id) AS total_loan_amount, (SELECT COUNT(*) FROM accts a JOIN loan l ON l.account_id = a.account_id WHERE l.status = 'A') AS good_loans, (SELECT COUNT(*) FROM accts a JOIN loan l ON l.account_id = a.account_id WHERE l.status = 'B') AS bad_loans, (SELECT COUNT(*) FROM accts WHERE STRFTIME('%m', date) IN ('01','02','03')) AS q1_accounts, (SELECT COUNT(*) FROM accts WHERE STRFTIME('%m', date) IN ('04','05','06')) AS q2_accounts, (SELECT COUNT(*) FROM accts WHERE STRFTIME('%m', date) IN ('07','08','09')) AS q3_accounts, (SELECT COUNT(*) FROM accts WHERE STRFTIME('%m', date) IN ('10','11','12')) AS q4_accounts	financial
SELECT a.account_id, d.A2 AS account_district_name, d.A3 AS account_region, a.frequency AS account_frequency, (SELECT COUNT(*) FROM trans t WHERE t.account_id = a.account_id AND t.type = 'PRIJEM') AS incoming_count, (SELECT COALESCE(SUM(t.amount), 0) FROM trans t WHERE t.account_id = a.account_id AND t.type = 'PRIJEM') AS incoming_total, (SELECT COUNT(*) FROM trans t WHERE t.account_id = a.account_id AND t.type = 'VYDAJ') AS outgoing_count, (SELECT COALESCE(SUM(t.amount), 0) FROM trans t WHERE t.account_id = a.account_id AND t.type = 'VYDAJ') AS outgoing_total, (SELECT COUNT(*) FROM card c JOIN disp dc ON c.disp_id = dc.disp_id WHERE dc.account_id = a.account_id) AS card_count, (SELECT COUNT(*) FROM loan l WHERE l.account_id = a.account_id) AS loan_count, (SELECT COUNT(*) FROM "order" o WHERE o.account_id = a.account_id) AS order_count, d.A10 AS urban_population_ratio, d.A11 AS avg_salary, d.A12 AS unemployment_rate_1995, d.A13 AS unemployment_rate_1996, d.A14 AS entrepreneurs_per_1000, d.A15 AS crimes_1995, d.A16 AS crimes_1996 FROM disp dp JOIN account a ON a.account_id = dp.account_id JOIN district d ON d.district_id = a.district_id WHERE dp.client_id = ( SELECT client_id FROM client WHERE gender = 'F' AND birth_date = '1976-01-29' ) AND dp.type = 'OWNER' ORDER BY a.account_id	financial
SELECT d.A2 AS district_name, d.A4 AS number_of_inhabitants, COUNT(c.client_id) AS total_clients, SUM(CASE WHEN c.gender = 'M' THEN 1 ELSE 0 END) AS male_clients, CAST(SUM(CASE WHEN c.gender = 'M' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(c.client_id) AS percentage_male_clients FROM district d JOIN client c ON c.district_id = d.district_id WHERE d.A3 = 'south Bohemia' GROUP BY d.district_id, d.A2, d.A4 ORDER BY d.A4 DESC LIMIT 1	financial
WITH under_loans AS ( SELECT l.loan_id, l.amount, l.status, d.A3 AS region, CASE WHEN l.amount < 50000 THEN 'Small' ELSE 'Medium' END AS loan_size_category FROM loan l JOIN account a ON l.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE l.amount < 100000 ), overall AS ( SELECT 100.0 * SUM(CASE WHEN status = 'C' THEN 1 ELSE 0 END) / COUNT(*) AS overall_pct FROM under_loans ) SELECT u.region, u.loan_size_category, 100.0 * SUM(CASE WHEN u.status = 'C' THEN 1 ELSE 0 END) / COUNT(*) AS pct_running_no_issues, o.overall_pct AS overall_pct_running_no_issues, 100.0 * SUM(CASE WHEN u.status = 'C' THEN 1 ELSE 0 END) / COUNT(*) - o.overall_pct AS diff_from_overall_pct FROM under_loans u CROSS JOIN overall o GROUP BY u.region, u.loan_size_category, o.overall_pct ORDER BY u.region, u.loan_size_category	financial
WITH base_accounts AS ( SELECT account_id, district_id FROM account WHERE frequency = 'POPLATEK PO OBRATU' AND substr(date, 1, 4) = '1993' ), district_list AS ( SELECT DISTINCT district_id FROM base_accounts ), txn AS ( SELECT b.district_id, COUNT(t.trans_id) AS transaction_count, SUM(CASE WHEN t.type = 'PRIJEM' THEN t.amount ELSE 0 END) AS total_income, SUM(CASE WHEN t.type = 'VYDAJ' THEN t.amount ELSE 0 END) AS total_expense FROM base_accounts b JOIN trans t ON t.account_id = b.account_id GROUP BY b.district_id ), client_agg AS ( SELECT b.district_id, COUNT(DISTINCT c.client_id) AS client_count, COUNT(DISTINCT CASE WHEN c.gender = 'M' THEN c.client_id END) AS male_client_count, COUNT(DISTINCT CASE WHEN c.gender = 'F' THEN c.client_id END) AS female_client_count FROM base_accounts b JOIN disp d ON d.account_id = b.account_id JOIN client c ON c.client_id = d.client_id GROUP BY b.district_id ), loan_agg AS ( SELECT b.district_id, COUNT(l.loan_id) AS loan_count, SUM(CASE WHEN l.status = 'A' THEN 1 ELSE 0 END) AS running_loan_count, SUM(CASE WHEN l.status = 'B' THEN 1 ELSE 0 END) AS finished_loan_count, SUM(CASE WHEN l.status = 'C' THEN 1 ELSE 0 END) AS defaulted_loan_count FROM base_accounts b JOIN loan l ON l.account_id = b.account_id GROUP BY b.district_id ) SELECT d.A2 AS district_name, d.A3 AS region, d.A10 AS urban_ratio, COALESCE(t.transaction_count, 0) AS transaction_count, COALESCE(t.total_income, 0) AS total_income, COALESCE(t.total_expense, 0) AS total_expense, COALESCE(c.client_count, 0) AS client_count, COALESCE(c.male_client_count, 0) AS male_client_count, COALESCE(c.female_client_count, 0) AS female_client_count, COALESCE(l.loan_count, 0) AS loan_count, COALESCE(l.running_loan_count, 0) AS running_loan_count, COALESCE(l.finished_loan_count, 0) AS finished_loan_count, COALESCE(l.defaulted_loan_count, 0) AS defaulted_loan_count, CASE WHEN COALESCE(l.loan_count, 0) = 0 THEN 0.0 ELSE ROUND(100.0 * COALESCE(l.defaulted_loan_count, 0) / COALESCE(l.loan_count, 0), 2) END AS default_rate FROM district_list dl JOIN district d ON d.district_id = dl.district_id LEFT JOIN txn t ON t.district_id = dl.district_id LEFT JOIN client_agg c ON c.district_id = dl.district_id LEFT JOIN loan_agg l ON l.district_id = dl.district_id ORDER BY d.A2	financial
WITH acct AS ( SELECT a.account_id, d.A2 AS district_name, a.date AS account_opened_date, a.frequency AS account_frequency FROM account a JOIN district d ON a.district_id = d.district_id WHERE d.A2 = 'Prachatice' ), owner_demographics AS ( SELECT di.account_id, c.gender AS owner_gender, c.birth_date AS owner_birth_date FROM disp di JOIN client c ON di.client_id = c.client_id WHERE di.type = 'OWNER' ), txn_stats AS ( SELECT account_id, SUM(CASE WHEN type = 'PRIJEM' THEN amount ELSE 0 END) AS total_income, SUM(CASE WHEN type = 'VYDAJ' THEN amount ELSE 0 END) AS total_expense, COUNT(trans_id) AS transaction_count FROM trans GROUP BY account_id ), loan_stats AS ( SELECT account_id, COUNT(loan_id) AS loan_count, SUM(amount) AS total_loan_amount FROM loan GROUP BY account_id ) SELECT acct.account_id, acct.district_name, acct.account_opened_date, acct.account_frequency, od.owner_gender, od.owner_birth_date, COALESCE(ts.total_income, 0) AS total_income, COALESCE(ts.total_expense, 0) AS total_expense, COALESCE(ts.total_income, 0) - COALESCE(ts.total_expense, 0) AS net_balance, COALESCE(ts.transaction_count, 0) AS transaction_count, COALESCE(ls.loan_count, 0) AS loan_count, COALESCE(ls.total_loan_amount, 0) AS total_loan_amount, CASE WHEN COALESCE(ls.loan_count, 0) > 0 AND COALESCE(ts.transaction_count, 0) > 10 THEN 'High Activity' WHEN COALESCE(ls.loan_count, 0) > 0 THEN 'Loan Customer' WHEN COALESCE(ts.transaction_count, 0) > 10 THEN 'Active Customer' ELSE 'Regular Customer' END AS customer_category FROM acct LEFT JOIN owner_demographics od ON acct.account_id = od.account_id LEFT JOIN txn_stats ts ON acct.account_id = ts.account_id LEFT JOIN loan_stats ls ON acct.account_id = ls.account_id ORDER BY net_balance DESC	financial
WITH tx_stats AS ( SELECT account_id, COUNT(*) AS transaction_count, SUM(CASE WHEN type = 'PRIJEM' THEN amount ELSE 0 END) AS total_income, SUM(CASE WHEN type = 'VYDAJ' THEN amount ELSE 0 END) AS total_expense FROM trans GROUP BY account_id ), all_loan_ranks AS ( SELECT a.account_id, d.A3 AS region, MAX(l.amount) AS max_loan_amount, RANK() OVER (PARTITION BY d.A3 ORDER BY MAX(l.amount) DESC) AS region_loan_rank FROM account a JOIN district d ON d.district_id = a.district_id JOIN loan l ON l.account_id = a.account_id GROUP BY a.account_id, d.A3 ), candidates AS ( SELECT a.account_id, d.A2 AS district, d.A3 AS region, l.amount AS loan_amount, l.duration AS loan_duration, l.payments AS loan_payments, l.status AS loan_status, c.gender, c.birth_date, CASE WHEN COALESCE(tx.total_income, 0) > 1000000 THEN 'High Income' WHEN COALESCE(tx.total_income, 0) > 500000 THEN 'Medium Income' ELSE 'Low Income' END AS income_classification, COALESCE(tx.transaction_count, 0) AS transaction_count, CASE WHEN tx.total_income IS NULL OR tx.total_income = 0 THEN NULL ELSE CAST(tx.total_income - tx.total_expense AS REAL) / tx.total_income END AS savings_ratio, alr.region_loan_rank FROM account a JOIN district d ON d.district_id = a.district_id JOIN loan l ON l.account_id = a.account_id JOIN all_loan_ranks alr ON alr.account_id = a.account_id JOIN disp dp ON dp.account_id = a.account_id AND dp.type = 'OWNER' JOIN client c ON c.client_id = dp.client_id LEFT JOIN tx_stats tx ON tx.account_id = a.account_id WHERE l.amount > 300000 AND d.A11 > (SELECT AVG(A11) FROM district) AND (tx.account_id IS NULL OR tx.total_income - tx.total_expense > 0) ) SELECT account_id, district, region, loan_amount, loan_duration, loan_payments, loan_status, gender, birth_date, income_classification, transaction_count, savings_ratio, region_loan_rank FROM candidates ORDER BY loan_amount DESC LIMIT 100	financial
WITH ranked AS ( SELECT l.loan_id, l.account_id, l.date AS loan_date, l.amount, l.duration, l.payments, l.status, a.district_id, ROW_NUMBER() OVER ( PARTITION BY a.district_id ORDER BY l.amount DESC, l.loan_id ASC ) AS rn FROM loan AS l JOIN account AS a ON l.account_id = a.account_id WHERE l.duration = 60 ) SELECT d.A2 AS district_name, d.A11 AS average_salary, r.loan_id, r.loan_date, r.amount AS loan_amount, r.duration AS loan_duration_months, r.payments AS monthly_payment, r.status AS loan_status, c.gender AS client_gender, c.birth_date AS client_birth_date, t.date AS transaction_date, t.amount AS transaction_amount, (r.payments * r.duration - r.amount) * 100.0 / r.amount AS interest_rate FROM ranked AS r JOIN district AS d ON d.district_id = r.district_id JOIN disp AS dp ON dp.account_id = r.account_id AND dp.type = 'OWNER' JOIN client AS c ON c.client_id = dp.client_id LEFT JOIN trans AS t ON t.account_id = r.account_id WHERE r.rn <= 3 ORDER BY d.A11 DESC, r.amount DESC, r.loan_id ASC, t.date ASC	financial
SELECT DISTINCT d.A2 AS district, ((d.A13 - d.A12) / d.A12) * 100 AS unemployment_rate_increment_pct FROM loan l JOIN account a ON l.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE l.status = 'D'	financial
WITH county_avg AS ( SELECT SUM("Free Meal Count (K-12)") * 1.0 / SUM("Enrollment (K-12)") AS avg_rate FROM frpm WHERE "County Name" = 'Alameda' ), top_school AS ( SELECT "CDSCode", "School Name", ("Free Meal Count (K-12)" * 1.0 / "Enrollment (K-12)") AS free_meal_rate FROM frpm WHERE "County Name" = 'Alameda' ORDER BY free_meal_rate DESC LIMIT 1 ) SELECT ts."School Name", ts.free_meal_rate AS "Free Meal Rate", ca.avg_rate AS "County Average Free Meal Rate", ts.free_meal_rate - ca.avg_rate AS "Free Meal Rate Deviation", sc."Charter" AS "Charter", sc."GSserved" AS "Grades Served", CASE WHEN sat.cds IS NULL OR sat.AvgScrRead IS NULL OR sat.AvgScrMath IS NULL OR sat.AvgScrWrite IS NULL THEN 'No SAT Data' WHEN (sat.AvgScrRead + sat.AvgScrMath + sat.AvgScrWrite) < 1200 THEN 'Below Average' WHEN (sat.AvgScrRead + sat.AvgScrMath + sat.AvgScrWrite) <= 1500 THEN 'Average' ELSE 'Above Average' END AS "SAT Performance Level" FROM top_school ts CROSS JOIN county_avg ca LEFT JOIN schools sc ON ts."CDSCode" = sc."CDSCode" LEFT JOIN satscores sat ON ts."CDSCode" = sat.cds	california_schools
WITH charter AS ( SELECT sch.CDSCode, sch.School, sch.Street, sch.City, sch.State, sch.Zip, frpm."Enrollment (K-12)" AS EnrollmentK12, frpm."FRPM Count (K-12)" AS FRPMCountK12, CAST(frpm."FRPM Count (K-12)" AS REAL) / NULLIF(frpm."Enrollment (K-12)", 0) * 100 AS FRPMEligibilityRate, sch.OpenDate, sch.StatusType FROM schools sch JOIN frpm ON frpm.CDSCode = sch.CDSCode WHERE sch.District = 'Fresno County Office of Education' AND frpm."Charter School (Y/N)" = 1 ) SELECT c.School AS SchoolName, c.Street, c.City, c.State, c.Zip, c.EnrollmentK12, c.FRPMCountK12, c.FRPMEligibilityRate, CASE WHEN c.FRPMEligibilityRate > 75 THEN 'High FRPM' WHEN c.FRPMEligibilityRate >= 50 THEN 'Medium FRPM' ELSE 'Low FRPM' END AS FRPMCategory, sat.AvgScrRead, sat.AvgScrMath, sat.AvgScrWrite, sat.NumTstTakr, sat.NumGE1500, CASE WHEN sat.NumTstTakr > 0 THEN CAST(sat.NumGE1500 AS REAL) / sat.NumTstTakr * 100 ELSE NULL END AS ExcellenceRate, RANK() OVER (ORDER BY sat.AvgScrRead DESC) AS ReadingRank, RANK() OVER (ORDER BY sat.AvgScrMath DESC) AS MathRank, RANK() OVER (ORDER BY sat.AvgScrWrite DESC) AS WritingRank, STRFTIME('%Y', c.OpenDate) AS YearOpened, c.StatusType FROM charter c LEFT JOIN satscores sat ON sat.cds = c.CDSCode ORDER BY c.School	california_schools
WITH top AS ( SELECT CDSCode FROM frpm WHERE "Charter School (Y/N)" = 0 AND "Enrollment (K-12)" > 100 ORDER BY "FRPM Count (K-12)" DESC LIMIT 1 ) SELECT sch.School AS school_name, sch.Street, sch.City, sch.State, sch.Zip, sch.MailStreet AS mailing_street, sch.MailCity AS mailing_city, sch.MailState AS mailing_state, sch.MailZip AS mailing_zip, sch.Website, fr."Enrollment (K-12)" AS enrollment_k12, fr."FRPM Count (K-12)" AS frpm_eligible_k12, ROUND(fr."Percent (%) Eligible FRPM (K-12)" * 100, 2) AS frpm_percent, sat.NumTstTakr AS sat_test_takers, sat.NumGE1500 AS sat_num_ge1500, ROUND(CAST(sat.NumGE1500 AS REAL) * 100 / sat.NumTstTakr, 2) AS sat_ge1500_percent, sat.AvgScrRead AS sat_avg_read, sat.AvgScrMath AS sat_avg_math, sat.AvgScrWrite AS sat_avg_write, CASE WHEN fr."Percent (%) Eligible FRPM (K-12)" * 100 > 70 AND CAST(sat.NumGE1500 AS REAL) * 100 / sat.NumTstTakr > 20 THEN 'unexpectedly well' WHEN fr."Percent (%) Eligible FRPM (K-12)" * 100 < 30 AND CAST(sat.NumGE1500 AS REAL) * 100 / sat.NumTstTakr < 10 THEN 'unexpectedly poorly' ELSE 'neither' END AS unexpected_performance FROM top JOIN frpm fr ON fr.CDSCode = top.CDSCode JOIN schools sch ON sch.CDSCode = top.CDSCode LEFT JOIN satscores sat ON sat.cds = top.CDSCode AND sat.rtype = 'S'	california_schools
SELECT sch.School AS school_name, sat.AvgScrMath AS avg_sat_math, sat.AvgScrRead AS avg_sat_read, sat.AvgScrWrite AS avg_sat_write, (sat.AvgScrRead + sat.AvgScrMath + sat.AvgScrWrite) AS total_sat_score, RANK() OVER (ORDER BY (sat.AvgScrRead + sat.AvgScrMath + sat.AvgScrWrite) DESC) AS sat_performance_rank, frpm."Enrollment (K-12)" AS enrollment_k12, frpm."Percent (%) Eligible FRPM (K-12)" AS frpm_percent FROM schools sch JOIN satscores sat ON sch.CDSCode = sat.cds JOIN frpm ON sch.CDSCode = frpm.CDSCode WHERE sch.Virtual = 'F' AND sat.AvgScrMath > 400 ORDER BY total_sat_score DESC	california_schools
WITH base AS ( SELECT s.School AS school_name, sat.AvgScrRead AS avg_reading_score, sat.AvgScrMath AS avg_math_score, sat.AvgScrWrite AS avg_writing_score, (sat.AvgScrRead + sat.AvgScrMath + sat.AvgScrWrite) AS total_avg_sat_score, f."Percent (%) Eligible FRPM (K-12)" AS frpm_proportion FROM schools s JOIN satscores sat ON s.CDSCode = sat.cds JOIN frpm f ON f.CDSCode = s.CDSCode WHERE s.Magnet = 1 AND sat.NumTstTakr > 500 ) SELECT school_name, avg_reading_score, avg_math_score, avg_writing_score, total_avg_sat_score, RANK() OVER (ORDER BY total_avg_sat_score DESC) AS performance_rank, ROUND(frpm_proportion * 100, 2) AS frpm_percent, CASE WHEN frpm_proportion >= 0.75 THEN 'High Poverty' WHEN frpm_proportion >= 0.50 THEN 'Moderate Poverty' WHEN frpm_proportion >= 0.25 THEN 'Low Poverty' ELSE 'Very Low Poverty' END AS poverty_level, CASE WHEN total_avg_sat_score >= 1800 THEN 'Excellent' WHEN total_avg_sat_score >= 1500 THEN 'Good' WHEN total_avg_sat_score >= 1200 THEN 'Average' ELSE 'Below Average' END AS performance_category FROM base ORDER BY total_avg_sat_score DESC	california_schools
SELECT s."School" AS school_name, s."Street" AS street, s."City" AS city, s."State" AS state, s."Zip" AS zip, fr."School Type" AS school_type, fr."FRPM Count (K-12)" AS frpm_count, fr."Percent (%) Eligible FRPM (K-12)" AS frpm_eligible_percent, fr."Free Meal Count (K-12)" AS free_meal_count, fr."Percent (%) Eligible Free (K-12)" AS free_meal_eligible_percent, sat."AvgScrRead" AS sat_avg_read, sat."AvgScrMath" AS sat_avg_math, sat."AvgScrWrite" AS sat_avg_write, sat."NumGE1500" AS sat_num_ge1500 FROM frpm AS fr LEFT JOIN schools AS s ON s."CDSCode" = fr."CDSCode" LEFT JOIN satscores AS sat ON sat."cds" = fr."CDSCode" ORDER BY fr."FRPM Count (K-12)" DESC LIMIT 10	california_schools
WITH top AS ( SELECT CAST(cds AS INTEGER) AS cds_int, AvgScrRead, AvgScrMath, AvgScrWrite FROM satscores WHERE rtype = 'S' AND NumTstTakr > 10 ORDER BY AvgScrRead DESC LIMIT 1 ) SELECT sch.County, sch.District, sch.School, sch.Street, sch.City, sch.Zip, sch.State, s.AvgScrRead, s.AvgScrMath, s.AvgScrWrite, fr."FRPM Count (K-12)", fr."Percent (%) Eligible FRPM (K-12)", fr."Enrollment (K-12)", sch.Charter FROM top s JOIN schools sch ON sch.CDSCode = printf('%014d', s.cds_int) JOIN frpm fr ON fr.CDSCode = printf('%014d', s.cds_int)	california_schools
SELECT s.School, s.County, s.District, s.Street, s.City, s.Zip, s.Phone, s.Website, s.Charter, s.Magnet, s.Latitude, s.Longitude FROM satscores sat JOIN frpm f ON sat.cds = f.CDSCode JOIN schools s ON s.CDSCode = f.CDSCode WHERE s.StatusType = 'Active' AND sat.NumTstTakr > 0 AND f."Enrollment (Ages 5-17)" > 0 AND CAST(sat.NumGE1500 AS REAL) / sat.NumTstTakr > 0.3 ORDER BY CAST(f."Free Meal Count (Ages 5-17)" AS REAL) / f."Enrollment (Ages 5-17)" DESC LIMIT 1	california_schools
SELECT sc.School AS SchoolName, sc.Phone AS ContactNumber, sc.City AS City, sc.Charter AS CharterStatus, CASE WHEN f."Percent (%) Eligible FRPM (K-12)" > 0.75 THEN 'High Poverty' WHEN f."Percent (%) Eligible FRPM (K-12)" > 0.50 THEN 'Medium Poverty' WHEN f."Percent (%) Eligible FRPM (K-12)" > 0.25 THEN 'Low Poverty' ELSE 'Very Low Poverty' END AS PovertyClassification FROM satscores s JOIN schools sc ON s.cds = sc.CDSCode JOIN frpm f ON s.cds = f.CDSCode WHERE s.rtype = 'S' AND s.NumTstTakr > 0 AND s.NumGE1500 IS NOT NULL ORDER BY CAST(s.NumGE1500 AS REAL) / s.NumTstTakr DESC LIMIT 3	california_schools
SELECT CASE WHEN s.NumTstTakr < 50 THEN 'under 50 testers' WHEN s.NumTstTakr <= 100 THEN '50-100 testers' WHEN s.NumTstTakr <= 250 THEN '100-250 testers' END AS testing_volume, s.AvgScrRead, s.AvgScrMath, s.AvgScrWrite, sc.County, sc.District, sc.School, sc.Charter, sc.FundingType, sc.GSoffered, sc.GSserved, sc.Virtual, sc.Magnet FROM satscores s JOIN frpm f ON s.cds = f.CDSCode JOIN schools sc ON s.cds = sc.CDSCode WHERE f."Charter Funding Type" = 'Directly funded' AND sc.County = 'Fresno' AND sc.Charter = 1 AND s.NumTstTakr <= 250 ORDER BY CASE WHEN s.NumTstTakr < 50 THEN 1 WHEN s.NumTstTakr <= 100 THEN 2 WHEN s.NumTstTakr <= 250 THEN 3 END, s.NumTstTakr, sc.School	california_schools
SELECT s.School, s.Phone, s.Ext, s.Website, s.AdmEmail1, s.Street, s.City, s.Zip, s.State, ss.AvgScrRead, ss.AvgScrMath, ss.AvgScrWrite, ss.NumGE1500, f."Charter School (Y/N)", f."Enrollment (K-12)", f."Percent (%) Eligible FRPM (K-12)" FROM satscores ss JOIN schools s ON ss.cds = s.CDSCode LEFT JOIN frpm f ON f.CDSCode = s.CDSCode WHERE ss.rtype = 'S' AND s.StatusType = 'Active' AND ss.NumTstTakr >= 10 ORDER BY ss.AvgScrMath DESC LIMIT 1	california_schools
SELECT AVG(frpm."Free Meal Count (K-12)" * 100.0 / frpm."Enrollment (K-12)") AS avg_free_meal_pct, SUM(CASE WHEN s.Charter = 1 THEN 1 ELSE 0 END) AS charter_count, SUM(CASE WHEN s.Charter = 0 THEN 1 ELSE 0 END) AS non_charter_count, SUM(sa.total_score * sa.NumTstTakr) / NULLIF(SUM(CASE WHEN sa.total_score IS NOT NULL THEN sa.NumTstTakr ELSE 0 END), 0) AS avg_sat_score, SUM(CASE WHEN frpm."Free Meal Count (K-12)" > 600 THEN 1 ELSE 0 END) AS very_high_count, SUM(CASE WHEN frpm."Free Meal Count (K-12)" > 500 AND frpm."Free Meal Count (K-12)" <= 600 THEN 1 ELSE 0 END) AS high_count, SUM(CASE WHEN frpm."Free Meal Count (K-12)" <= 500 THEN 1 ELSE 0 END) AS moderate_count FROM frpm JOIN schools s ON s.CDSCode = frpm.CDSCode LEFT JOIN ( SELECT cds, (AvgScrRead + AvgScrMath + AvgScrWrite) AS total_score, NumTstTakr FROM satscores ) sa ON sa.cds = frpm.CDSCode WHERE s.County = 'Los Angeles' AND frpm."Free Meal Count (K-12)" > 500 AND frpm."FRPM Count (K-12)" < 700	california_schools
SELECT c.gender, CASE WHEN CAST((julianday(a.date) - julianday(c.birth_date)) / 365.2425 AS INTEGER) < 30 THEN 'Young' WHEN CAST((julianday(a.date) - julianday(c.birth_date)) / 365.2425 AS INTEGER) BETWEEN 30 AND 50 THEN 'Middle-aged' ELSE 'Senior' END AS age_group, dst.A3 AS region, COUNT(DISTINCT c.client_id) AS owner_count, SUM(CASE WHEN t.type = 'PRIJEM' THEN t.amount ELSE 0 END) AS total_income, SUM(CASE WHEN t.type = 'VYDAJ' THEN t.amount ELSE 0 END) AS total_expense, AVG(t.balance) AS avg_balance FROM account a JOIN disp dp ON dp.account_id = a.account_id AND dp.type = 'OWNER' JOIN client c ON c.client_id = dp.client_id JOIN district dst ON dst.district_id = c.district_id JOIN trans t ON t.account_id = a.account_id WHERE a.frequency = 'POPLATEK TYDNE' GROUP BY c.gender, age_group, dst.A3	financial
WITH disps AS ( SELECT d.disp_id, d.client_id, d.account_id FROM disp d JOIN account a ON a.account_id = d.account_id WHERE d.type = 'DISPONENT' AND a.frequency = 'POPLATEK PO OBRATU' ), loan_stats AS ( SELECT l.account_id, COUNT(*) AS loan_count, SUM(CASE WHEN l.status = 'A' THEN 1 ELSE 0 END) AS active_loan_count, SUM(CASE WHEN l.status = 'B' THEN 1 ELSE 0 END) AS completed_loan_count, SUM(l.amount) AS total_loan_amount, SUM(l.payments) AS total_loan_payments FROM loan l GROUP BY l.account_id ), trans_stats AS ( SELECT t.account_id, COUNT(*) AS transaction_count, SUM(t.amount) AS transaction_volume FROM trans t GROUP BY t.account_id ) SELECT c.client_id, c.gender, c.birth_date, MAX(a.frequency) AS service_usage, COALESCE(SUM(ls.loan_count), 0) AS loan_count, COALESCE(SUM(ls.active_loan_count), 0) AS active_loan_count, COALESCE(SUM(ls.completed_loan_count), 0) AS completed_loan_count, COALESCE(SUM(ls.total_loan_amount), 0) AS total_loan_amount, COALESCE(SUM(ls.total_loan_payments), 0) AS total_loan_payments, COALESCE(SUM(ts.transaction_count), 0) AS transaction_count, COALESCE(SUM(ts.transaction_volume), 0) AS transaction_volume, GROUP_CONCAT(DISTINCT crd.type) AS credit_card_type FROM disps d JOIN account a ON a.account_id = d.account_id JOIN client c ON c.client_id = d.client_id LEFT JOIN loan_stats ls ON ls.account_id = d.account_id LEFT JOIN trans_stats ts ON ts.account_id = d.account_id LEFT JOIN card crd ON crd.disp_id = d.disp_id GROUP BY c.client_id, c.gender, c.birth_date ORDER BY transaction_volume DESC	financial
WITH base AS ( SELECT d.client_id, d.account_id, cl.gender, cl.birth_date, dstr.A2 AS district_name, dstr.A3 AS region, CAST((julianday(c.issued) - julianday(cl.birth_date)) / 365.25 AS INTEGER) AS age_at_issue FROM card c JOIN disp d ON c.disp_id = d.disp_id JOIN client cl ON d.client_id = cl.client_id LEFT JOIN district dstr ON cl.district_id = dstr.district_id WHERE date(c.issued) = '1994-03-03' ), loan_agg AS ( SELECT l.account_id, COUNT(*) AS loan_count, SUM(CASE WHEN l.status = 'A' THEN 1 ELSE 0 END) AS active_loan_count, SUM(l.amount) AS total_loan_amount FROM loan l GROUP BY l.account_id ), trans_agg AS ( SELECT t.account_id, COUNT(*) AS trans_count, SUM(t.amount) AS total_transaction_amount FROM trans t GROUP BY t.account_id ) SELECT b.client_id, b.gender, b.birth_date, b.age_at_issue, CASE WHEN COALESCE(l.loan_count, 0) > 0 AND b.age_at_issue < 30 THEN 'Young borrower' WHEN COALESCE(l.loan_count, 0) > 0 AND b.age_at_issue >= 30 THEN 'Mature borrower' ELSE 'Non-borrower' END AS borrower_category, RANK() OVER (PARTITION BY b.gender ORDER BY b.age_at_issue DESC) AS age_rank_within_gender, b.district_name, b.region, COALESCE(t.trans_count, 0) AS trans_count, COALESCE(t.total_transaction_amount, 0) AS total_transaction_amount, COALESCE(l.loan_count, 0) AS loan_count, COALESCE(l.active_loan_count, 0) AS active_loan_count, COALESCE(l.total_loan_amount, 0) AS total_loan_amount FROM base b LEFT JOIN loan_agg l ON b.account_id = l.account_id LEFT JOIN trans_agg t ON b.account_id = t.account_id ORDER BY b.gender, b.age_at_issue DESC	financial
SELECT date(a.date) AS account_opened_date, CAST(julianday('1998-10-14') - julianday(a.date) AS INTEGER) AS days_open, c.gender AS owner_gender, CAST(strftime('%Y','1998-10-14') AS INTEGER) - CAST(strftime('%Y', c.birth_date) AS INTEGER) - (strftime('%m-%d','1998-10-14') < strftime('%m-%d', c.birth_date)) AS owner_age, (SELECT COUNT(*) FROM trans t WHERE t.account_id=a.account_id AND date(t.date) <= '1998-10-14') AS total_transactions_up_to_date, (SELECT COUNT(*) FROM card cd JOIN disp dd ON cd.disp_id=dd.disp_id WHERE dd.account_id=a.account_id) AS cards_issued, CASE WHEN EXISTS (SELECT 1 FROM loan l WHERE l.account_id=a.account_id AND date(l.date) < '1998-10-14') THEN 1 ELSE 0 END AS had_loan_before FROM account a JOIN disp d ON d.account_id=a.account_id AND d.type='OWNER' JOIN client c ON c.client_id=d.client_id WHERE a.account_id = (SELECT t.account_id FROM trans t WHERE t.amount=840 AND date(t.date)='1998-10-14' LIMIT 1)	financial
WITH target AS ( SELECT d.client_id, d.account_id FROM card c JOIN disp d ON d.disp_id = c.disp_id WHERE date(c.issued) = '1996-10-21' ), largest_txn AS ( SELECT t.* FROM trans t JOIN target tg ON tg.account_id = t.account_id ORDER BY t.amount DESC, t.trans_id ASC LIMIT 1 ) SELECT lt.trans_id, lt.account_id AS transaction_account_id, lt.date AS transaction_date, lt.type AS transaction_type, lt.operation, lt.amount AS max_amount, lt.balance, lt.k_symbol AS transaction_k_symbol, lt.bank AS transaction_bank, lt.account AS transaction_counter_account, cl.client_id, cl.gender, cl.birth_date, dt.district_id, dt.A2 AS district_name, dt.A3 AS region, dt.A4, dt.A5, dt.A6, dt.A7, dt.A8, dt.A9, dt.A10, dt.A11, dt.A12, dt.A13, dt.A14, dt.A15, dt.A16, l.loan_id, l.account_id AS loan_account_id, l.date AS loan_date, l.amount AS loan_amount, l.duration, l.payments, l.status AS loan_status, o.order_id, o.account_id AS order_account_id, o.bank_to, o.account_to, o.amount AS order_amount, o.k_symbol AS order_k_symbol FROM largest_txn lt JOIN target tg ON tg.account_id = lt.account_id JOIN client cl ON cl.client_id = tg.client_id JOIN district dt ON dt.district_id = cl.district_id LEFT JOIN loan l ON l.account_id = tg.account_id LEFT JOIN "order" o ON o.account_id = tg.account_id	financial
WITH target AS ( SELECT l.*, dp.disp_id, dp.client_id FROM loan l JOIN disp dp ON dp.account_id = l.account_id AND dp.type = 'OWNER' WHERE l.amount = 98832 AND l.date = '1996-01-03' ) SELECT c.birth_date AS birthday, CAST((julianday(tgt.date) - julianday(c.birth_date)) / 365.25 AS INTEGER) AS age_at_loan_application, d.A2 AS location, (SELECT COUNT(*) FROM trans t WHERE t.account_id = tgt.account_id AND t.date < tgt.date) AS transaction_count_before_loan, ROUND( (SELECT SUM(CASE WHEN t.type = 'VYDAJ' THEN t.amount ELSE 0 END) * 100.0 / NULLIF(SUM(CASE WHEN t.type = 'PRIJEM' THEN t.amount ELSE 0 END), 0) FROM trans t WHERE t.account_id = tgt.account_id AND t.date < tgt.date), 2) AS expense_to_income_ratio_pct, (SELECT MIN(t.balance) FROM trans t WHERE t.account_id = tgt.account_id AND t.date < tgt.date) AS min_balance, (SELECT MAX(t.balance) FROM trans t WHERE t.account_id = tgt.account_id AND t.date < tgt.date) AS max_balance, cd.type AS credit_card_type, cd.issued AS credit_card_issued, (SELECT COUNT(*) FROM loan l2 WHERE l2.date < tgt.date AND l2.account_id IN (SELECT di.account_id FROM disp di WHERE di.client_id = tgt.client_id) ) AS previous_loan_count FROM target tgt JOIN client c ON c.client_id = tgt.client_id LEFT JOIN district d ON d.district_id = c.district_id LEFT JOIN card cd ON cd.disp_id = tgt.disp_id	financial
SELECT d.A3 AS region, 100.0 * SUM(CASE WHEN l.status = 'A' THEN l.amount ELSE 0 END) / SUM(l.amount) AS pct_amount_fully_paid, 100.0 * COUNT(CASE WHEN l.status = 'A' THEN 1 END) / COUNT(*) AS pct_loans_completed, AVG(CASE WHEN l.status = 'A' THEN l.payments * l.duration - l.amount END) AS avg_interest_successful, AVG(l.payments * l.duration - l.amount) AS avg_interest_all FROM loan l JOIN account a ON l.account_id = a.account_id JOIN district d ON a.district_id = d.district_id GROUP BY d.A3 ORDER BY d.A3	financial
WITH target AS ( SELECT l.loan_id, l.account_id, l.date AS loan_date, l.amount, l.duration, l.payments, l.status, a.district_id FROM loan l JOIN account a ON a.account_id = l.account_id WHERE l.loan_id = 4990 ) SELECT t.loan_id, c.gender, c.birth_date, t.loan_date, t.amount, t.duration, t.payments, CASE t.status WHEN 'A' THEN 'Running - OK' WHEN 'B' THEN 'Running - Issues' WHEN 'C' THEN 'Finished - No Issues' WHEN 'D' THEN 'Finished - Issues' ELSE t.status END AS status_description, d.A2 AS district_name, d.A3 AS region, d.A11 AS average_salary, d.A12 AS unemployment_rate_1995, ( SELECT COUNT(*) + 1 FROM loan l2 JOIN account a2 ON a2.account_id = l2.account_id WHERE a2.district_id = t.district_id AND l2.loan_id <> 4990 AND l2.amount > t.amount ) AS district_loan_rank FROM target t JOIN disp dp ON dp.account_id = t.account_id AND dp.type = 'OWNER' JOIN client c ON c.client_id = dp.client_id JOIN district d ON d.district_id = t.district_id	financial
WITH school_data AS ( SELECT f."County Name" AS county_name, f."School Name" AS school_name, f."Enrollment (K-12)" AS enrollment_k12, f."Enrollment (Ages 5-17)" AS enrollment_ages_5_17, f."Enrollment (K-12)" + f."Enrollment (Ages 5-17)" AS total_enrollment, f."Percent (%) Eligible Free (K-12)" AS pct_free_k12, f."Percent (%) Eligible FRPM (K-12)" AS pct_frpm_k12, CASE WHEN f."Percent (%) Eligible FRPM (K-12)" >= 0.75 THEN 'High' WHEN f."Percent (%) Eligible FRPM (K-12)" >= 0.50 THEN 'Medium' ELSE 'Low' END AS frpm_level, f."Charter School (Y/N)" AS charter_status, s.NumTstTakr AS num_tst_takr, s.NumGE1500 AS num_ge1500, CASE WHEN s.NumTstTakr > 0 THEN CAST(s.NumGE1500 AS REAL) * 100.0 / s.NumTstTakr ELSE NULL END AS pct_sat_ge1500, s.AvgScrRead AS avg_scr_read, s.AvgScrMath AS avg_scr_math, s.AvgScrWrite AS avg_scr_write, s.AvgScrRead + s.AvgScrMath + s.AvgScrWrite AS total_sat FROM frpm f JOIN satscores s ON CAST(f.CDSCode AS INTEGER) = CAST(s.cds AS INTEGER) WHERE s.rtype = 'S' AND f."Enrollment (K-12)" + f."Enrollment (Ages 5-17)" > 500 AND ( f."Percent (%) Eligible FRPM (K-12)" > 0.60 OR ( s.NumTstTakr > 0 AND CAST(s.NumGE1500 AS REAL) * 100.0 / s.NumTstTakr > 30.0 ) ) ) SELECT county_name, school_name, enrollment_k12, enrollment_ages_5_17, total_enrollment, pct_free_k12, pct_frpm_k12, frpm_level, charter_status, num_tst_takr, num_ge1500, pct_sat_ge1500, avg_scr_read, avg_scr_math, avg_scr_write, total_sat, RANK() OVER (PARTITION BY county_name ORDER BY total_enrollment DESC) AS county_enrollment_rank, RANK() OVER (PARTITION BY frpm_level ORDER BY total_sat DESC) AS frpm_sat_rank FROM school_data ORDER BY county_name, frpm_level, county_enrollment_rank, frpm_sat_rank	california_schools
WITH hs AS ( SELECT * FROM frpm WHERE "County Name" = 'Amador' AND "Low Grade" = '9' AND "High Grade" = '12' ) SELECT COUNT(*) AS total_high_schools, AVG("Enrollment (K-12)") AS avg_enrollment, SUM(CASE WHEN "Charter School (Y/N)" = 1 THEN 1 ELSE 0 END) AS charter_schools, SUM(CASE WHEN "Charter School (Y/N)" = 0 THEN 1 ELSE 0 END) AS non_charter_schools, AVG("Percent (%) Eligible FRPM (K-12)") AS avg_poverty_rate, COUNT(DISTINCT "District Code") AS num_districts, AVG(s."AvgScrRead") AS avg_sat_read, AVG(s."AvgScrMath") AS avg_sat_math, AVG(s."AvgScrWrite") AS avg_sat_write, (SELECT h2."School Name" FROM hs h2 ORDER BY h2."Enrollment (K-12)" DESC LIMIT 1) AS largest_school, SUM(CASE WHEN "Percent (%) Eligible FRPM (K-12)" > 0.75 THEN 1 ELSE 0 END) AS high_poverty_schools FROM hs LEFT JOIN satscores s ON s."rtype" = 'S' AND s."cds" = substr(hs."CDSCode", 1, 2) || substr(hs."CDSCode", 4)	california_schools
WITH la_noncharter AS ( SELECT "School Name", "Enrollment (K-12)", "Free Meal Count (K-12)", "Free Meal Count (K-12)" * 100.0 / "Enrollment (K-12)" AS exact_free_meal_pct FROM frpm WHERE "Charter School (Y/N)" = 0 AND "County Name" = 'Los Angeles' ), ranked AS ( SELECT "School Name", "Enrollment (K-12)", "Free Meal Count (K-12)", exact_free_meal_pct, RANK() OVER (ORDER BY exact_free_meal_pct ASC) AS rank_within_county, (SELECT COUNT(*) FROM la_noncharter WHERE exact_free_meal_pct < 0.18) AS low_free_meal_school_count FROM la_noncharter ) SELECT "School Name", "Enrollment (K-12)", "Free Meal Count (K-12)", exact_free_meal_pct, rank_within_county, low_free_meal_school_count FROM ranked WHERE exact_free_meal_pct < 0.18 ORDER BY exact_free_meal_pct ASC	california_schools
SELECT v.School FROM virtual_schools v ORDER BY v.enrollment DESC LIMIT 1 ) AS largest_virtual_school FROM county_stats cs ORDER BY cs.virtual_school_count DESC LIMIT 1	california_schools
SELECT "School Type", "School Name" FROM frpm WHERE "County Code" = '37' AND "NSLP Provision Status" = 'Breakfast Provision 2'	california_schools
SELECT COUNT(DISTINCT account.account_id) FROM account JOIN district ON account.district_id = district.district_id WHERE account.frequency = 'POPLATEK PO OBRATU' AND district.A3 = 'east Bohemia'	financial
SELECT COUNT(*) FROM client JOIN district ON client.district_id = district.district_id WHERE client.gender = 'M' AND district.A3 = 'north Bohemia' AND district.A11 > 8000	financial
SELECT DISTINCT a.account_id FROM account a JOIN loan l ON a.account_id = l.account_id WHERE substr(l.date, 1, 4) = '1997' AND a.frequency = 'POPLATEK TYDNE' AND l.amount = ( SELECT MIN(l2.amount) FROM loan l2 JOIN account a2 ON a2.account_id = l2.account_id WHERE substr(l2.date, 1, 4) = '1997' AND a2.frequency = 'POPLATEK TYDNE' ) ORDER BY a.account_id	financial
SELECT a.account_id FROM account a JOIN loan l ON a.account_id = l.account_id WHERE l.duration > 12 AND a.date >= '1993-01-01' AND a.date < '1994-01-01' ORDER BY l.amount DESC LIMIT 1	financial
SELECT CAST("Free Meal Count (Ages 5-17)" AS REAL) / CAST("Enrollment (Ages 5-17)" AS REAL) AS eligible_free_rate FROM frpm WHERE "Educational Option Type" = 'Continuation School' AND "Free Meal Count (Ages 5-17)" IS NOT NULL AND "Enrollment (Ages 5-17)" IS NOT NULL ORDER BY eligible_free_rate ASC LIMIT 3	california_schools
SELECT schools.Phone FROM schools JOIN frpm ON schools.CDSCode = frpm.CDSCode WHERE frpm."Charter School (Y/N)" = 1 AND frpm."Charter Funding Type" = 'Directly funded' AND schools.OpenDate > '2000-01-01'	california_schools
SELECT s.School, s.Street, s.City, s.State, s.Zip FROM frpm f JOIN schools s ON f.CDSCode = s.CDSCode WHERE f."County Name" = 'Monterey' AND f."School Type" = 'High Schools (Public)' AND f."FRPM Count (Ages 5-17)" > 800	california_schools
SELECT "frpm"."Free Meal Count (Ages 5-17)" * 1.0 / "frpm"."Enrollment (Ages 5-17)" AS free_rate FROM "schools" JOIN "frpm" ON "schools"."CDSCode" = "frpm"."CDSCode" WHERE "schools"."AdmFName1" = 'Kacey' AND "schools"."AdmLName1" = 'Gibson'	california_schools
